// Server-only data access. The JSON files are generated by scripts/convert_xlsx.py
// and imported here, so they stay on the server and never ship to the browser.
import "server-only";
import concordance from "@/data/concordance.json";
import kuralData from "@/data/kural.json";
import morph from "@/data/morph.json";

// [literature index, poem no, line no, segmented/parsed line, original line]
export type Line = [number, number, number, string, string];

export type Kural = { n: number; ch: number; seg: string[]; orig: string[]; first: string; last: string };

export const LIMIT = 400; // max result rows rendered on one page

// ------------------------------------------------------------------ Concordance
export const conLits: string[] = concordance.lits;
export const conLines = concordance.lines as Line[];
export const conWords: string[] = concordance.words;

// word -> indexes into conLines, built once per server process (35k lines, a few ms)
const conIndex = new Map<string, number[]>();
conLines.forEach((l, i) => {
  for (const t of new Set(l[3].split(" "))) {
    const list = conIndex.get(t);
    if (list) list.push(i);
    else conIndex.set(t, [i]);
  }
});

export function conOccurrences(word: string, lit?: number): Line[] {
  const hits = (conIndex.get(word) ?? []).map((i) => conLines[i]);
  return lit === undefined ? hits : hits.filter((l) => l[0] === lit);
}

// ------------------------------------------------------------------ Thirukkural
export const chapters: string[] = kuralData.chapters;
export const kurals = kuralData.kurals as Kural[];

// The three books (paal) and the chapters they span.
export const paals = [
  { name: "அறத்துப்பால்", from: 1, to: 38 },
  { name: "பொருட்பால்", from: 39, to: 108 },
  { name: "காமத்துப்பால்", from: 109, to: 133 },
];

export const initialWords = sortedUnique(kurals.map((k) => k.first));
export const finalWords = sortedUnique(kurals.map((k) => k.last));

function sortedUnique(words: string[]) {
  // keep the Tamil dictionary order of the source data: first appearance in a pre-sorted list
  const order = new Map(conWords.map((w, i) => [w, i]));
  return [...new Set(words)].sort(
    (a, b) => (order.get(a) ?? 1e9) - (order.get(b) ?? 1e9) || a.localeCompare(b, "ta"),
  );
}

// ------------------------------------------------------------- Morphology + dictionary
export const morphLits: string[] = morph.lits;
export const morphLines = morph.lines as Line[];
// [word, English meanings, occurs in parsed corpus]
export const dictionary = morph.dictionary as [string, string, boolean][];
// [code, English, Tamil]
export const grammar = morph.grammar as [string, string, string][];

export function morphTokenHits(token: string, lit?: number): Line[] {
  return morphLines.filter((l) => (lit === undefined || l[0] === lit) && l[3].split(" ").includes(token));
}

export function morphTextHits(text: string, lit?: number): Line[] {
  return morphLines.filter((l) => (lit === undefined || l[0] === lit) && (l[3].includes(text) || l[4].includes(text)));
}

// ------------------------------------------------------------------ helpers
/** Literatures that are one long poem (the Pattuppattu): cite them by line only. */
function singlePoem(lines: Line[]) {
  const poems = new Map<number, Set<number>>();
  for (const l of lines) poems.set(l[0], (poems.get(l[0]) ?? new Set()).add(l[1]));
  return new Set([...poems].filter(([, p]) => p.size === 1).map(([lit]) => lit));
}
export const conSingle = singlePoem(conLines);
export const morphSingle = singlePoem(morphLines);

export function litIndex(list: string[], name?: string) {
  const i = name ? list.indexOf(name) : -1;
  return i === -1 ? undefined : i;
}

export function one(v: string | string[] | undefined) {
  return (Array.isArray(v) ? v[0] : v)?.trim() || undefined;
}
